window.ScripturaLexicons.BDAG_PART_0148 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hesperinos-bdag\" data-source=\"BDAG\" data-search=\"ἑσπερινός, ή, όν hesperinós adjetivo vespertino; relativo ao anoitecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑσπερινός, ή, όν</td><td>adjetivo</td><td>vespertino; relativo ao anoitecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hesrom-bdag\" data-source=\"BDAG\" data-search=\"Ἑσρώμ, ὁ Hesrṓm nome próprio masculino indeclinável Esrom; nome na genealogia de Jesus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἑσρώμ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Esrom; nome na genealogia de Jesus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hessoomai-bdag\" data-source=\"BDAG\" data-search=\"ἑσσόομαι hessóomai verbo médio-passivo ser inferior; ficar em desvantagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑσσόομαι</td><td>verbo médio-passivo</td><td>ser inferior; ficar em desvantagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-estathen-hestanai-hesteka-esten-estesa-bdag\" data-source=\"BDAG\" data-search=\"ἐστάθην, ἑστάναι, ἕστηκα, ἔστην, ἔστησα estáthēn, hestánai, héstēka, éstēn, éstēsa formas verbais remissivas ver ἵστημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐστάθην, ἑστάναι, ἕστηκα, ἔστην, ἔστησα</td><td>formas verbais remissivas</td><td>ver ἵστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-estraphen-bdag\" data-source=\"BDAG\" data-search=\"ἐστράφην estráphēn forma verbal remissiva ver στρέφω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐστράφην</td><td>forma verbal remissiva</td><td>ver στρέφω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-estromenos-estosan-bdag\" data-source=\"BDAG\" data-search=\"ἐστρωμένος, ἔστωσαν estrōménos, éstōsan formas verbais remissivas ver στρώννυμι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐστρωμένος, ἔστωσαν</td><td>formas verbais remissivas</td><td>ver στρώννυμι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-esto-bdag\" data-source=\"BDAG\" data-search=\"ἔστω éstō forma verbal remissiva ver εἰμί BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔστω</td><td>forma verbal remissiva</td><td>ver εἰμί</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hestos-bdag\" data-source=\"BDAG\" data-search=\"ἑστώς hestṓs forma verbal remissiva ver ἵσταμαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑστώς</td><td>forma verbal remissiva</td><td>ver ἵσταμαι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-estosan-bdag\" data-source=\"BDAG\" data-search=\"ἔστωσαν éstōsan forma verbal remissiva ver εἰμί BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔστωσαν</td><td>forma verbal remissiva</td><td>ver εἰμί</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-esphage-bdag\" data-source=\"BDAG\" data-search=\"ἐσφάγη esphágē forma verbal remissiva ver σφάζω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐσφάγη</td><td>forma verbal remissiva</td><td>ver σφάζω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eschatos-bdag\" data-source=\"BDAG\" data-search=\"ἔσχατος, η, ον éschatos adjetivo; substantivado e adverbial último; derradeiro; mais remoto; menos importante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔσχατος, η, ον</td><td>adjetivo; substantivado e adverbial</td><td>último; derradeiro; mais remoto; menos importante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eschatos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἐσχάτως eschátōs advérbio finalmente; no extremo; à beira da morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐσχάτως</td><td>advérbio</td><td>finalmente; no extremo; à beira da morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eso-bdag\" data-source=\"BDAG\" data-search=\"ἔσω ésō advérbio de lugar para dentro; dentro; interior BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔσω</td><td>advérbio de lugar</td><td>para dentro; dentro; interior</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-esothen-bdag\" data-source=\"BDAG\" data-search=\"ἔσωθεν ésōthen advérbio de lugar de dentro; interiormente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔσωθεν</td><td>advérbio de lugar</td><td>de dentro; interiormente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-esoteros-bdag\" data-source=\"BDAG\" data-search=\"ἐσώτερος, α, ον esṓteros adjetivo comparativo mais interior; interno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐσώτερος, α, ον</td><td>adjetivo comparativo</td><td>mais interior; interno</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hetairos-bdag\" data-source=\"BDAG\" data-search=\"ἑταῖρος, ου, ὁ hetaîros substantivo masculino companheiro; camarada; membro do grupo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑταῖρος, ου, ὁ</td><td>substantivo masculino</td><td>companheiro; camarada; membro do grupo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-etarachthen-bdag\" data-source=\"BDAG\" data-search=\"ἐταράχθην etaráchthēn forma verbal remissiva ver ταράσσω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐταράχθην</td><td>forma verbal remissiva</td><td>ver ταράσσω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-etaphe-bdag\" data-source=\"BDAG\" data-search=\"ἐτάφη etáphē forma verbal remissiva ver θάπτω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐτάφη</td><td>forma verbal remissiva</td><td>ver θάπτω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-etethen-bdag\" data-source=\"BDAG\" data-search=\"ἐτέθην etéthēn forma verbal remissiva ver τίθημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐτέθην</td><td>forma verbal remissiva</td><td>ver τίθημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-etekon-bdag\" data-source=\"BDAG\" data-search=\"ἔτεκον étekon forma verbal remissiva ver τίκτω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔτεκον</td><td>forma verbal remissiva</td><td>ver τίκτω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-hesperinos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑσπερινός, ή, όν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hesperinós⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver o verbete anterior. Atestado desde Xenofonte, Resp. Lac. 12, 6; POxy 901, 5; BGU 1024 VI, 6; LXX. Relativo ao anoitecer, vespertino, da tarde: <span class=\"greek\">φυλακή</span>, a primeira vigília da noite, das seis às nove horas da noite (18h–21h), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:38</a>, variante textual. — M-M.</p></section></article>\n<article id=\"entry-hesrom-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑσρώμ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Hesrṓm⟧</span><span class=\"separator\">·</span><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Também <span class=\"greek\">Ἐ</span>-, <span class=\"greek\">Ἑσρών</span> e <span class=\"greek\">Ἐσρών</span>; indeclinável. Esrom, na genealogia de Jesus (1 Cr 2:5, variante textual, e 2:9; em Rt 4:18s., variante textual), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:33</a>.</p></section></article>\n<article id=\"entry-hessoomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑσσόομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hessóomai⟧</span><span class=\"separator\">·</span><span>verbo médio-passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Aoristo primeiro: <span class=\"greek\">ἡσσώθην</span>. Forma jônica de <span class=\"greek\">ἡσσάομαι</span> (Heródoto 1, 82, 3; 2, 169, 1; 8, 130, 2; ver J. Wackernagel, Hellenistica, 1907, 17–19; B-D-F §34, 1; Mlt-H. 107; 240; 396; diferentemente, W-S. §15, p. 127).</p><p class=\"entry-text\">Ser colocado em circunstâncias ou condição inferiores ou piores; ser inferior a, ou estar em situação pior do que: <span class=\"greek\">τί</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἡσσώθητε</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">λοιπὰς</span> <span class=\"greek\">ἐκκλησίας</span>; «Pois em que aspecto vos fizeram sentir menos importantes do que as outras congregações?» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 12:13</a> (<span class=\"greek\">ἡττήθητε</span>, variante textual). — F. Zorell, BZ 9, 1911, 160s.; DELG, s.v. <span class=\"greek\">ἦκα</span>.</p></section></article>\n<article id=\"entry-estathen-hestanai-hesteka-esten-estesa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐστάθην, ἑστάναι, ἕστηκα, ἔστην, ἔστησα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦estáthēn, hestánai, héstēka, éstēn, éstēsa⟧</span><span class=\"separator\">·</span><span>formas verbais remissivas</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">ἵστημι</span>.</p></section></article>\n<article id=\"entry-estraphen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐστράφην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦estráphēn⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">στρέφω</span>.</p></section></article>\n<article id=\"entry-estromenos-estosan-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐστρωμένος, ἔστωσαν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦estrōménos, éstōsan⟧</span><span class=\"separator\">·</span><span>formas verbais remissivas</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">στρώννυμι</span>.</p></section></article>\n<article id=\"entry-esto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔστω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éstō⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">εἰμί</span>.</p></section></article>\n<article id=\"entry-hestos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑστώς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hestṓs⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">ἵσταμαι</span>.</p></section></article>\n<article id=\"entry-estosan-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔστωσαν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éstōsan⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">εἰμί</span>.</p></section></article>\n<article id=\"entry-esphage-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐσφάγη</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦esphágē⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">σφάζω</span>.</p></section></article>\n<article id=\"entry-eschatos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔσχατος, η, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éschatos⟧</span><span class=\"separator\">·</span><span>adjetivo; substantivado e adverbial</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e posteriores.) Significado geral: «último».</p><p class=\"entry-text\">① Relativo a estar no limite mais distante de uma área: o mais longínquo, o último. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔσχατος</span> <span class=\"greek\">τόπος</span>, talvez deva ser entendido espacialmente como «o lugar no canto mais afastado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:9</a>s. (mas ver ② abaixo). — Substantivado: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔσχατον</span>, «o extremo», «o fim» (escólio a Apolônio de Rodes 4, 1515a, p. 319, 19: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔσχατον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νήσου</span>; PTebt 68, 54 [séc. II a.C.], acerca de documento). <span class=\"greek\">ἕως</span> <span class=\"greek\">ἐσχάτου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, «até os confins da terra» (Is 48:20; 62:11; 1 Mac 3:9; PsSol 1:4; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, TestSol 7:6 D), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:8</a> (C. Burchard, D. Dreizehnte Zeuge, 1970, 134, nota 309; E. Ellis, «The End of the Earth», Acts 1:8, Bulletin for Biblical Research 1, 1991, 123–32, tradução de seu texto em Der Treue Gottes Trauen, Beiträge … für Gerhard Schneider, org. C. Bussmann e W. Radl, 1991, 277–86 [Lucas teria escrito em meados da década de 60 e Paulo teria chegado a Gades, na Espanha]; B. Becking, 573–76); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.47\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:47</a>; B 14:8 (as duas últimas referências citam Is 49:6). No plural (Hesíodo, Theog. 731, e um oráculo em Heródoto 7, 140: <span class=\"greek\">ἔσχατα</span> <span class=\"greek\">γαίης</span>; Xenofonte, Vect. 1, 6; Diodoro Sículo 1, 60, 5; Élio Aristides 35, 14 K.=9, p. 103 D.: <span class=\"greek\">ἔσχ</span>. <span class=\"greek\">γῆς</span>; Crates, Ep. 31, e Demóstenes, Ep. 4, 7: <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἔσχατα</span> <span class=\"greek\">γῆς</span>), <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, «os confins da terra», 1 Cl 28:3 (Teócrito 15, 8; escólio a Apolônio de Rodes 2, 413–18b; com <span class=\"greek\">εἰς</span> antes da expressão, Sl 138:9).</p><p class=\"entry-text\">② Relativo a ser o elemento final de uma série: o menos importante, o último no tempo.</p><p class=\"entry-text\">ⓐ Aquele que vem por último, ou o último que resta, em relação a algo precedente: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:12</a>, 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:6</a>, 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:9</a>, variante textual. Em oposição a <span class=\"greek\">πρῶτος</span> (2 Cr 9:29 e outras passagens; Sir 24:28; 41:3): <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἕως</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρώτων</span>, «dos últimos até os primeiros», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:8</a>; cf. 27:64; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.45\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15:45</a> (<span class=\"greek\">ἔ</span>. também se refere ao posterior de dois, como Dt 24:3s.: <span class=\"greek\">ἔ</span>. … <span class=\"greek\">πρότερος</span>; por isso, em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.47\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15:47</a>, foi substituído por <span class=\"greek\">δεύτερος</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:31</a>, variante textual: <span class=\"greek\">ὁ</span>. <span class=\"greek\">ἔ</span>., «o segundo», «o último dos dois». Acerca de coisas, <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔσχατα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:19</a>; Hv 1, 4, 2. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔσχατα</span> (em contraste com <span class=\"greek\">τὰ</span> <span class=\"greek\">πρῶτα</span>, como em Jó 8:7; TestSol 26:8), «o estado final», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2:20</a>. Acerca da criação nos últimos dias: <span class=\"greek\">ποιῶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἔσχατα</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πρῶτα</span>, «faço as últimas coisas como as primeiras» (citação apócrifa; cf. Hipólito, Comentário a Daniel 4:37), B 6:13.</p><p class=\"entry-text\">ⓑ Com referência a uma situação em que nada se segue ao <span class=\"greek\">ἔ</span>. (Diodoro Sículo 19, 59, 6: <span class=\"greek\">κρίσιν</span> <span class=\"greek\">ἐσχάτην</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Δημήτριον</span> <span class=\"greek\">βασιλείας</span>, «a última [definitiva] crise no reinado de Demétrio»; TestAbr B 3, p. 108, 3 [Stone, p. 64]: <span class=\"greek\">ἐσχατός</span> <span class=\"greek\">μού</span> <span class=\"greek\">ἐστιν</span>): <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἑορτῆς</span>, «o último dia da festa» (cf. 2 Esdr 18:18), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:37</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span>, «o último dia da vida», Hv 3, 12, 2; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐσχάτῃ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἡμέρᾳ</span>, «nos últimos dias da vida dele», GJs 1:3 (cf. ApcEsd 7:10: <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔσχατα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰωσήφ</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">κοδράντης</span>, «o último quadrante» (cf. 2 Esdr 15:15), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:59</a>, variante textual; D 1:5; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15:26</a>, 52; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 15:1</a>; 21:9. <span class=\"greek\">τὴν</span> … <span class=\"greek\">ἐ</span>. <span class=\"greek\">ῥάβδον</span>, «a última vara», GJs 9:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ῥήματα</span>, «as palavras finais» (de um discurso), Hv 1, 3, 3. Como autodesignação do Senhor ressuscitado: <span class=\"greek\">ὁ</span> <span class=\"greek\">πρῶτος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἒ</span>., «o primeiro e o último», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:17</a>; 2:8; 22:13.</p><p class=\"entry-text\">Especialmente acerca dos últimos dias, por vezes concebidos como iniciados com o nascimento de Cristo, por vezes com sua segunda vinda: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἡμέρα</span>, «o último dia» (P. Viereck, Sermo Gr., quo senatus pop. Rom. magistratusque … usi sunt, 1888, inscrição 29, 9 [116 a.C.]: <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐσχάτην</span> <span class=\"greek\">ἡμέραν</span>, «para sempre»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:39</a>s., 44, 54; 11:24; 12:48 (ApcMos 41; B. Aebert, D. Eschatol. des J, diss. Breslau 1936); Hv 2, 2, 5. No plural (Is 2:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:3</a>; D 16:3; B 4:9. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτου</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">τούτων</span> (Nm 24:14; Jr 23:20; 25:19), «nestes últimos dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:2</a>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμερῶν</span> (Os 3:5; Jr 37:24; Ez 38:16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 3:3</a> (cf. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτων</span> <span class=\"greek\">χρόνων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1:20</a>, variante textual); 2 Cl 14:2; B 12:9; 16:5; Hs 9, 12, 3; GJs 7:2. — <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χρόνου</span>, Jd 18; <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χρόνων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1:20</a>. — <span class=\"greek\">ἔ</span>. <span class=\"greek\">καιρός</span>, v. 5; D 16:2. No plural (TestIss 6:1: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐσχάτοις</span> <span class=\"greek\">καιροῖς</span>), IEph 11:1. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐ</span>. [<span class=\"greek\">κα</span>]<span class=\"greek\">ι̣ρ̣</span>[<span class=\"greek\">ῶ</span>]<span class=\"greek\">ν̣</span>, AcPl Ha 8, 25 (Ox 1602, 39s. lê <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐ̣</span>|<span class=\"greek\">σ</span>‌̣<span class=\"greek\">χάτῳ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">καιρῶν</span>; cf. BMM reto 33; ApcMos 13). — <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὥρα</span> (Teles, p. 17, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 2:18</a>. — O neutro <span class=\"greek\">ἔσχατον</span> usado como advérbio, «por fim», «finalmente» (SIG 1219, 11 [séc. III a.C.]; POxy 886, 21; Nm 31:2; Pv 29:21; Taciano 35, 1): <span class=\"greek\">ἔ</span>. <span class=\"greek\">πάντων</span>, «por último de todos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15:8</a> (P. Jones, TynBull 36, 1985, 3–34). Ver bibliografia em <span class=\"greek\">παρουσία</span>.</p><p class=\"entry-text\">③ Relativo ao extremo mais distante quanto a posição, valor ou situação: último; o menos importante, o mais insignificante (em oposição a <span class=\"greek\">πρῶτος</span>, como em Hiérocles 23, p. 468: o ser humano é <span class=\"greek\">ἔσχατος</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἄνω</span>, <span class=\"greek\">πρῶτος</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κάτω</span>): (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πρῶτοι</span> <span class=\"greek\">ἔσχατοι</span> <span class=\"greek\">καὶ</span> (<span class=\"greek\">οἱ</span>) <span class=\"greek\">ἔσχατοι</span> <span class=\"greek\">πρῶτοι</span>, «os primeiros serão últimos e os últimos, primeiros», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:30</a>; 20:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:35</a> (<span class=\"greek\">πάντων</span> <span class=\"greek\">ἔσχατος</span>, como em Apiano, Bell. Civ. 2, 77, §322); 10:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:30</a>; Ox 654, 25 (reconstituído); 26 (=ASyn. 256, 55; GTh 4; Fitzmyer, Oxy., p. 523). <span class=\"greek\">τὸν</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τόπον</span> <span class=\"greek\">κατέχειν</span>, «ocupar o lugar menos honroso» (nesse sentido, <span class=\"greek\">ἔ</span>. <span class=\"greek\">τόπος</span> se oporia a <span class=\"greek\">ἐνδοξότερος</span>, como em Diógenes Laércio 2, 73), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:9</a>; cf. v. 10 (mas ver ① acima). Acerca dos apóstolos, que Deus apresentou como os menos importantes entre os homens em razão dos infortúnios sofridos (Diodoro Sículo 8, 18, 3: os <span class=\"greek\">ἔσχατοι</span> são pessoas na mais extrema miséria; Dião Crisóstomo 21 [38], 37: os tiranos vos tratam como <span class=\"greek\">ἐσχάτους</span>; Cássio Dião 42, 5, 5: <span class=\"greek\">Πομπήιος</span> … <span class=\"greek\">καθάπερ</span> <span class=\"greek\">τις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Αἰγυπτίων</span> <span class=\"greek\">ἔσχατος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 4:9</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">πιστῶν</span>, «o último dos fiéis», IEph 21:2; cf. ITr 13:1; IRo 9:2; ISm 11:1. Acerca de situação muito arriscada: extremo: <span class=\"greek\">εἰ</span> … <span class=\"greek\">ἔ</span>. <span class=\"greek\">κίνδυνον</span>, «em extremo perigo», AcPl Ha 4, 15s. (cf. Just., D. 46, 7: <span class=\"greek\">ὑπομένομεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τιμωρία</span>). — Em sentido positivo, máximo, supremo, excelente: <span class=\"greek\">εὐλόγησον</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἐσχάτην</span> <span class=\"greek\">εὐλογίαν</span>, «abençoa-a com a bênção suprema», GJs 6:2 (ver de Strycker ad loc.; cf. Just., D. 32, 1: <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">κατάρᾳ</span>, «com a pior maldição»). — B. 940. Cf. <span class=\"greek\">τελευταῖο</span>, Schmidt, Syn. IV 524–34; DELG; M-M; EDNT; TW; Sv.</p></section></article>\n<article id=\"entry-eschatos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐσχάτως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eschátōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver o verbete anterior; Hipócrates e outros; Xenofonte, An. 2, 6, 1. Relativo a estar no extremo final: finalmente. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἔχειν</span> (cf. a expressão latina «in extremis esse»), estar à beira da morte (Artemidoro 3, 60; o tema de alguém «estar à beira da morte» aparece em inscrições honoríficas relativas a médicos, para perpetuar sua habilidade e dedicação; ver, por exemplo, ZPE 25, 1977, 270–72, n.º 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:23</a>. — M-M.</p></section></article>\n<article id=\"entry-eso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ésō⟧</span><span class=\"separator\">·</span><span>advérbio de lugar</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Advérbio de lugar (Homero e outros empregam a forma <span class=\"greek\">εἴσω</span>, igualmente predominante em épocas posteriores. Na literatura aqui examinada, como na LXX [Thackeray 82], TestSol, JosAs 2:19 e ApcMos 19, emprega-se somente <span class=\"greek\">ἔσω</span>; o mesmo em SIG 989, 2 [séc. II a.C.]; UPZ 13, 17 [160 a.C.]; BGU 1127, 9 [18 a.C.]. Josefo, Bell. 6, 265, usa <span class=\"greek\">εἴσω</span>, mas Ant. 15, 398, <span class=\"greek\">ἔσω</span>).</p><p class=\"entry-text\">① Posição dentro de uma área: dentro, no interior. Quando empregado com verbos de movimento, a tradução inglesa preferível é «para dentro», «dentro»: <span class=\"greek\">εἰσελθὼν</span> <span class=\"greek\">ἔ</span>., «ele entrou» (Bel 19, Teodocião), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:58</a>; AcPl Ha 4, 3. <span class=\"greek\">ἕως</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αὐλήν</span>, «até dentro do pátio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.54\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:54</a> (<span class=\"greek\">ἔσω</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αὐλήν</span>, como PBas I, 19 [c. 600 d.C.]; <span class=\"greek\">ἔσω</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">παράδεισον</span>, ApcMos 19). Com genitivo de lugar (já em Homero), <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">αὐλῆς</span>, «para dentro do palácio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:16</a> (JosAs 2:19, «dentro»).</p><p class=\"entry-text\">② Quando não empregado com verbo de movimento, a tradução habitual é «dentro», «no interior», em oposição a «fora»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:22</a>, códice D, 23; <span class=\"greek\">ἦσαν</span> <span class=\"greek\">ἔ</span>., «eles estavam dentro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20:26</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">φλέβες</span>, «as veias internas», MPol 2:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἄνθρωπος</span>, «o ser humano interior», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3:16</a>. Também <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἄ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 4:16</a> (ver <span class=\"greek\">ἄνθρωπος</span> 5a e <span class=\"greek\">ἔξω</span> 1a<span class=\"greek\">β</span>). — <span class=\"greek\">οἱ</span> <span class=\"greek\">ἔ</span>., «os de dentro» (da comunidade cristã; Enéias Tático 1312, a respeito dos que estão na cidade), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 5:12</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>., «o interior» (Luciano, Nav. 38; Sacr. 13; oposto a <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔξω</span>; ver <span class=\"greek\">ἔξω</span> 1a<span class=\"greek\">β</span>), isto é, «a alma», 2 Cl 12:2, 4 (dito de Jesus e sua explicação). — DELG, s.v. <span class=\"greek\">εἰ</span>; M-M; EDNT; TW; Sv.</p></section></article>\n<article id=\"entry-esothen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔσωθεν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ésōthen⟧</span><span class=\"separator\">·</span><span>advérbio de lugar</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Advérbio de lugar (Ésquilo, Heródoto e outros; papiros; LXX; TestSol; TestAbr A 12, p. 90, 20 [Stone, p. 28]; JosAs 10:8).</p><p class=\"entry-text\">① Extensão a partir de uma origem localizada no interior: de dentro (Heródoto 7, 36, 2; Enéias Tático 1636; Ath., R. 22, p. 75, 21), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:7</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐκπορεύεσθαι</span>, «sair de dentro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:23</a>; mais desenvolvidamente, <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span>, v. 21.</p><p class=\"entry-text\">② Relativo à parte interna de um objeto: dentro, interiormente (Heródoto e outros; Epicteto; POxy 1449, 44; LXX; TestAbr A 12, p. 90, 20 [Stone, p. 28]; EpArist 89; Josefo, Ant. 14, 477; 15, 424; Taciano 22, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:15</a>; 23:25, 27s.; IRo 7:2. <span class=\"greek\">αὐλὴν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:2</a>, variante textual. Empregado com <span class=\"greek\">ἔξωθεν</span> (Epicteto 4, 11, 18; Gn 6:14; Êx 25:11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 7:5</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔξωθεν</span>, «por dentro e por fora», IRo 3:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:1</a>, variante textual (para <span class=\"greek\">ἔσωθεν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὄπισθεν</span>, ver <span class=\"greek\">γράφω</span> 2b). <span class=\"greek\">κυκλόθεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔ</span>., «por todos os lados e por dentro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:8</a>. — <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ὑμῶν</span> (<span class=\"greek\">ὑμῖν</span> no P75), «vossa natureza interior», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:39</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔξωθεν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>., v. 40. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἔσωθεν</span> = <span class=\"greek\">οἱ</span> <span class=\"greek\">ἔσω</span> (ver <span class=\"greek\">ἔσω</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 5:12</a>, variante textual. — M-M; TW; Sv.</p></section></article>\n<article id=\"entry-esoteros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐσώτερος, α, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦esṓteros⟧</span><span class=\"separator\">·</span><span>adjetivo comparativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver o verbete anterior; PMagd 29, 10 [218 a.C.]; Mayser 14; 301; PRyl III, 478, 120: <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐσώτερος</span>; LXX. Comparativo de <span class=\"greek\">ἔσω</span>: mais interior, interno. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">φυλακή</span>, «a prisão interior», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:24</a> (sobre o assunto, ver Mommsen, Röm. Strafrecht, 1899, 302).</p><p class=\"entry-text\">Na expressão <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐσώτερον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">καταπετάσματος</span>, <span class=\"greek\">ἐ</span>. funciona como preposição com genitivo (cf. 1 Km 24:4): «o que está do lado de dentro (= atrás) da cortina», o Santo dos Santos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:19</a> (Lv 16:2, 12, 15). — DELG, s.v. <span class=\"greek\">εἰ</span>; M-M.</p></section></article>\n<article id=\"entry-hetairos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑταῖρος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hetaîros⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Homero e posteriores; também Ath. 31, 1 [variante textual <span class=\"greek\">ἑτέροι</span>]. Pessoa que compartilha alguma coisa com outras e desfruta de associação com elas, mas não necessariamente no grau de <span class=\"greek\">φίλος</span> ou <span class=\"greek\">φίλη</span>: camarada, companheiro; quanto a um membro do próprio grupo, «companheiro de grupo», D 14:2. Referindo-se a companheiros de brincadeira, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:16</a>, variante textual.</p><p class=\"entry-text\">Quanto aos discípulos de Jesus (Xenofonte, Mem. 2, 8, 1 e outras passagens: Sócrates chama seus discípulos de <span class=\"greek\">ἑ</span>.; Élio Aristides 47, p. 421 D.: <span class=\"greek\">οἱ</span> <span class=\"greek\">Πλάτωνος</span> <span class=\"greek\">ἑ</span>.; Porfírio, Vi. Pythag. 55, acerca de Pitágoras; Fílon, Vi. Cont. 40, acerca dos companheiros de Odisseu), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:50</a> (<span class=\"greek\">ἑταῖρε</span>; cf. Josefo, Ant. 12, 302, <span class=\"greek\">ὦ</span> <span class=\"greek\">ἑταῖροι</span>); GPt 7:26. <span class=\"greek\">Παπίας</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">Πολυκάρπου</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">γενόμενος</span>, «Pápias … que se tornou companheiro de Policarpo», Papias 1:2 (cf. 11:1).</p><p class=\"entry-text\">Como forma genérica de dirigir-se a alguém cujo nome não se conhece: <span class=\"greek\">ἑταῖρε</span>, «meu amigo» (Teógnis 753 Diehl; Aristófanes, Platão e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:13</a>; 22:12. — Em vez de ser uma variante por itacismo de <span class=\"greek\">ἕτερος</span>, a leitura <span class=\"greek\">ἑταῖροι</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:32</a> no P75 pode muito bem designar partidários políticos (cf. Lísias 43, 28). — J. Ernstman, <span class=\"greek\">Οἰκεῖος</span>, <span class=\"greek\">Ἑταῖρος</span>, <span class=\"greek\">Ἑπιτήδειος</span>, <span class=\"greek\">Φίλος</span>, diss. Utrecht, 1932; Schmidt, Syn. III 463–71; DELG; LfgrE, s.v. <span class=\"greek\">ἑ</span>. (bibliografia, col. 743); M-M; TW; Spicq; Sv.</p></section></article>\n<article id=\"entry-etarachthen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐταράχθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦etaráchthēn⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">ταράσσω</span>.</p></section></article>\n<article id=\"entry-etaphe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐτάφη</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦etáphē⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">θάπτω</span>.</p></section></article>\n<article id=\"entry-etethen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐτέθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦etéthēn⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">τίθημι</span>.</p></section></article>\n<article id=\"entry-etekon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔτεκον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦étekon⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão: ver <span class=\"greek\">τίκτω</span>.</p></section></article>\n"};
